const $=s=>document.querySelector(s), fmt=n=>n.toLocaleString('en-US'), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

