const iconFor=id=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(iconPaths[id]||iconPaths.market)+'"/></svg>';

const channels=['Market','Mobile Bus','Mobile Truck','Mini Market'];
const cities=['Bountiful','Woods Cross','Centerville','North Salt Lake','Farmington','Other'];
const seed=()=>({visits:Array.from({length:180},(_,i)=>({id:'D-'+(1000+i),household:'Demo household '+(i%75+1),size:2+i%5,city:cities[(i%75)%6],program:channels[i%10<6?0:i%10<8?1:i%10===8?2:3],date:`2026-09-${String(1+i%30).padStart(2,'0')}`,location:'bountiful',pounds:22+i%25})),outgoing:[],food:Array.from({length:24},(_,i)=>({id:'F-'+i,date:`2026-09-${String(1+i).padStart(2,'0')}`,category:['Produce','Dry goods','Dairy','Protein'][i%4],source:i%3?'Grocery Rescue':'Community donation',partner:'Demo partner '+(i%5+1),pounds:280+i*21,location:'bountiful'})),packs:[{date:'2026-09-04',count:480,location:'bountiful'},{date:'2026-09-11',count:520,location:'bountiful'},{date:'2026-09-18',count:460,location:'bountiful'},{date:'2026-09-25',count:540,location:'bountiful'}],notes:{director:'Demo narrative: Service demand remains steady. The next priority is to protect food availability while improving access across our mobile programs.',client:'Demo narrative: Mobile services are reaching households closer to home. Review the service mix alongside geographic reach.',operations:'Demo narrative: Grocery Rescue continues to support fresh-food availability. Dry goods are the next replenishment priority.',capital:'Demo narrative: Northern Davis remains a planning location. No activity from that location is included in current totals.'},volunteer:960});
let data;try{data=JSON.parse(localStorage.getItem('bfp-demo-v1'))||seed()}catch{data=seed()}data.visits.forEach(v=>{const m=/^Demo household (\d+)$/.exec(v.household);if(/^D-\d+$/.test(v.id)&&m)v.city=cities[(Number(m[1])-1)%cities.length]});data.outgoing ||= [];let view='home',preview=false;const save=()=>localStorage.setItem('bfp-demo-v1',JSON.stringify(data));
const views=[['home','⌂','Program home'],['daily','✓','Daily work'],['clients','♧','Client services'],['market','▦','Market'],['mobile','▥','Off-site Services'],['mini','▦','Mini Market'],['food','▤','Incoming / Outgoing Food'],['rescue','▤','Grocery Rescue'],['inventory','▤','Inventory'],['packs','▣','Pantry Packs'],['imports','⇧','Data Import Center'],['overview','◫','Executive overview'],['geography','◎','Geographic reach'],['reports','▥','Operational reports'],['board','▧','Board reporting']];
const meta={home:['Program home','Welcome to your Bountiful workspace.'],daily:['What do you need to do?','Choose a task. We’ll guide you through the few details needed.'],overview:['Your pantry, at a glance','See what needs attention and how your programs are serving the community.'],clients:['Client services','Find a household and record a visit in one place.'],market:['Market','Household grocery service at the pantry.'],mobile:['Off-site Services','Mobile Bus, Mobile Truck and off-site service in the community.'],mini:['Mini Market','A dedicated place for smaller neighborhood service events.'],food:['Incoming / Outgoing Food','Track food receipts, distributions and food drives.'],rescue:['Grocery Rescue','Review rescued food separately from other incoming food.'],inventory:['Inventory','Month-end inventory and reconciliation workspace.'],packs:['Pantry Packs','Track completed packs and distribution readiness.'],imports:['Data Import Center','One organized place for approved reporting uploads.'],geography:['Geographic reach','Understand where households live, across every service channel.'],reports:['Operational reports','Trace the numbers back to the activity that created them.'],board:['Board reporting','From daily activity to a board-ready report.']};
const scope=a=>a.filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value&&($('#location').value==='all'||x.location===$('#location').value));
function volunteerSummary(){try{const shared=JSON.parse(localStorage.getItem('bfp-volunteers-v1'));if(!shared||shared.version!==1||!Array.isArray(shared.hours))return null;const hours=scope(shared.hours).filter(h=>h.status==='Approved'&&Number.isFinite(Number(h.hours))&&Number(h.hours)>0);return {hours:hours.reduce((n,h)=>n+Number(h.hours),0),people:new Set(hours.map(h=>h.person)).size}}catch{return null}}
function stats(){let v=scope(data.visits),f=scope(data.food),p=scope(data.packs);return{volunteerData:volunteerSummary(),v,f,p,visits:v.length,households:new Set(v.map(x=>x.household)).size,people:v.reduce((n,x)=>n+x.size,0),out:v.reduce((n,x)=>n+x.pounds,0),incoming:f.reduce((n,x)=>n+x.pounds,0),packs:p.reduce((n,x)=>n+x.count,0),rescue:f.filter(x=>x.source==='Grocery Rescue').reduce((n,x)=>n+x.pounds,0)}}
const metric=(label,n,note)=>`<div class="card metric"><p>${label}</p><div class="value">${fmt(n)}</div><p>${note}</p></div>`;
const bars=(items,total)=>items.map(([name,n])=>`<div class="bar-row"><span>${esc(name)}</span><div class="bar"><i style="width:${total?n/total*100:0}%"></i></div><strong>${fmt(n)}</strong></div>`).join('');
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">No activity in this period.</td></tr>`}</tbody></table></div>`;
function render(){let s=stats();document.body.classList.toggle('program-home',view==='home');$('#nav').innerHTML=views.map(([id,icon,label],i)=>`${i===0?'<div class="nav-section">DAILY TASKS</div>':id==='overview'?'<div class="nav-section">LEADERSHIP & REPORTS</div>':''}<button data-view="${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}><span class="icon">${iconFor(id)}</span>${label}</button>`).join('');$('#title').textContent=meta[view][0];$('#subtitle').textContent=meta[view][1];$('#breadcrumb').textContent=view==='home'?'YOUR PROGRAMS':view==='daily'?'DAILY WORK':view==='overview'?'LEADERSHIP / OVERVIEW':'OPERATIONS / '+meta[view][0].toUpperCase();$('#periodStatus').textContent=$('#from').value>$('#to').value?'Choose an end date after the start date':'Live totals from demo activity';$('#mainAction').textContent=view==='food'?'Receive food':view==='rescue'?'Review rescue':view==='inventory'?'Review inventory':view==='imports'?'Import data':view==='packs'?'Record packs':view==='board'?'Preview report':view==='market'?'Record Market service':view==='mobile'?'Record mobile service':view==='mini'?'Record Mini Market service':'Record service';$('#mainAction').disabled=$('#location').value==='north';$('#mainAction').style.display=['home','daily','rescue','inventory','imports'].includes(view)?'none':'';$('.filterbar').style.display=view==='daily'?'none':'';
if($('#location').value==='north'){$('#content').innerHTML='<div class="card empty"><span class="badge">FUTURE LOCATION</span><h2>Northern Davis</h2><p>This location is reserved for a future operational system.</p><p class="muted">Its own activity, inventory, and programs will roll up into organization-wide reporting.<br>No simulated activity is counted here.</p><button onclick="document.querySelector(\'#location\').value=\'all\';render()">Return to all locations</button></div>';return}
let html='';if(view==='home'){html=`<section class="welcome-band"><div class="welcome-copy"><span class="welcome-label">THE WORK BEHIND THE GOOD</span><h1>Let’s make<br><em>today count.</em></h1><p>Five programs. One connected pantry. <br>Choose your workspace and get right to the good.</p><span class="welcome-period">Demo activity · ${$('#from').value} – ${$('#to').value}</span></div><div class="impact-panel"><div class="impact-title">Our work, together <span>SYNTHETIC DEMO</span></div><div class="impact-numbers"><div><strong>${fmt(s.households)}</strong><span>households reached</span></div><div><strong>${fmt(s.out)}</strong><span>pounds to households</span></div><div><strong>${fmt(s.packs)}</strong><span>Pantry Packs completed</span></div></div><div class="impact-footer"><span>Entered once. Connected everywhere.</span>${iconFor('overview')}</div></div></section><div class="program-section-title"><h2>Where are you working today?</h2><span>Your programs</span></div><div class="home-programs">${[['market','Market','Groceries, care, and a warm welcome.','Household service at the pantry',s.v.filter(x=>x.program==='Market').length,'service visits'],['mobile','Mobile','Take the pantry to the community.','Mobile Bus & Mobile Truck',s.v.filter(x=>['Mobile Bus','Mobile Truck'].includes(x.program)).length,'service visits'],['mini','Mini Market','Small markets. Local connections.','Neighborhood food service',s.v.filter(x=>x.program==='Mini Market').length,'service visits'],['packs','Pantry Packs','Pack a little extra possibility.','Pack completion & program totals',s.packs,'packs completed'],['food','Incoming / Outgoing Food','Keep good food moving.','Food receipts & inventory',s.incoming,'lb received']].map(([id,title,description,detail,n,unit])=>`<button class="program-choice choice-${id}" data-view="${id}"><div class="choice-top"><span class="tile-icon">${iconFor(id)}</span><span class="choice-label">${detail}</span></div><strong>${title}</strong><span class="choice-description">${description}</span><div class="choice-bottom"><span class="choice-count"><b>${fmt(n)}</b> ${unit}</span><span class="choice-open">Open workspace</span></div></button>`).join('')}</div><section class="home-leadership"><span class="leadership-icon">${iconFor('board')}</span><div><h2>A clear view of the bigger picture.</h2><p>Organization-wide dashboards and board-ready reporting.</p></div><div class="home-links"><a class="volunteer-link" href="volunteers/">Volunteer workspace →</a><button data-view="overview">Executive overview</button><button data-view="board">Board reporting</button></div></section>`;}
if(view==='rescue'){const rescue=s.f.filter(x=>x.source==='Grocery Rescue');html='<div class="grid three">'+metric('Grocery Rescue received (lb)',rescue.reduce((n,x)=>n+Number(x.pounds||0),0),'Demo receipts in the selected period')+metric('Rescue entries',rescue.length,'Daily source records')+metric('Reporting status','—','MealConnect integration not connected')+'</div><section class="card"><h2>Grocery Rescue records</h2><p>Rescue is tracked separately for reporting, while incoming food records remain the underlying source. MealConnect upload/import is pending feasibility review.</p>'+table(['Date','Source','Partner','Pounds'],rescue.map(x=>[esc(x.date),esc(x.source),esc(x.partner||'—'),fmt(Number(x.pounds||0))]))+'</section>';}
if(view==='inventory'){html=inventoryPanel(s);}
if(view==='daily'){html=`<div class="tasks"><section class="card task"><span class="tile-icon">${iconFor("clients")}</span><h2>Serve a household</h2><p>Choose the program you’re working in.</p><button class="primary" data-view="market">Market</button><button data-view="mobile">Mobile Bus & Mobile Truck</button><button data-view="mini">Mini Market</button><button data-view="clients">Find a household</button></section><section class="card task"><span class="tile-icon">${iconFor("food")}</span><h2>Receive food</h2><p>Record a Grocery Rescue pickup or a food donation.</p><button class="primary" data-add="food">Record incoming food</button></section><section class="card task"><span class="tile-icon">${iconFor("packs")}</span><h2>Finish Pantry Packs</h2><p>Enter the number of packs completed.</p><button class="primary" data-add="packs">Record completed packs</button></section></div><section class="card" style="margin-top:22px"><h2>You only need to enter it once</h2><p class="muted">After you save, the information is included in the pantry’s totals and reports automatically.</p></section>`;}if(view==='overview'){html=`<div class="metrics">${metric('Unique households',s.households,'Distinct households in selected period')}${metric('Service visits',s.visits,'Across all four service channels')}${metric('Food to clients',s.out,'Pounds recorded with service visits')}${metric('Pantry Packs completed',s.packs,'From program completion records')}</div><div class="grid"><section class="card"><div class="section-head"><div><h2>How we’re serving</h2><span class="muted">Service visits by program · selected period</span></div><div><button class="small-link" data-view="market">Market</button> · <button class="small-link" data-view="mobile">Mobile</button> · <button class="small-link" data-view="mini">Mini Market</button></div></div>${bars(channels.map(c=>[c,s.v.filter(x=>x.program===c).length]),s.visits)}<p class="muted">A household may visit more than once. Unique households and service visits are reported separately.</p></section><section class="card"><h2>Needs your attention</h2><div class="notice"><strong>Dry goods replenishment</strong>Demo planning signal: review the next Grocery Rescue pickups and upcoming mobile allocations.</div><div class="activity"><span class="tile-icon">${iconFor("board")}</span><div><strong>Board report ready to review</strong><div class="muted">Metrics assembled from the selected period</div></div><button class="small-link" data-view="board">Review</button></div><div class="activity"><span class="tile-icon">${iconFor("geography")}</span><div><strong>Northern Davis</strong><div class="muted">Planning only · excluded from current totals</div></div></div></section></div><div class="grid equal"><section class="card hero-card"><span class="eyebrow" style="color:#bdd7c5">FOOD MOVEMENT</span><h2>${fmt(s.incoming)} lb received</h2><p>${fmt(s.rescue)} lb from Grocery Rescue in this period.</p><button data-view="food">Open food operations</button></section><section class="card"><h2>Recent activity</h2>${s.v.slice(-3).reverse().map(x=>`<div class="activity"><span class="tile-icon">✓</span><div><strong>${esc(x.program)} service recorded</strong><div class="muted">${x.date} · ${esc(x.household)} · ${x.pounds} lb</div></div></div>`).join('')}</section></div>`}
if(view==='clients'){html=`<div class="metrics">${metric('Unique households',s.households,'De-duplicated within this reporting period')}${metric('Service visits',s.visits,'One record per completed visit')}${metric('Individuals served',s.people,'Person-visits; includes repeat visits')}${metric('Food to clients',s.out,'Pounds distributed')}</div><section class="card" style="margin-top:22px"><div class="toolbar"><input id="search" aria-label="Search households" placeholder="Search demo household, city, or ID"><select id="channel" aria-label="Filter service channel"><option value="">All service channels</option>${channels.map(c=>`<option>${c}</option>`).join('')}</select></div><div id="clientRows"></div></section>`}
if(['market','mobile','mini'].includes(view)){html=`<div class="programs ${view==='mobile'?'':'single-program'}">${channels.filter(c=>view==='market'?c==='Market':view==='mobile'?['Mobile Bus','Mobile Truck'].includes(c):c==='Mini Market').map(c=>{let i=channels.indexOf(c),v=s.v.filter(x=>x.program===c);return`<section class="card program program-${view}"><div class="section-head"><div class="program-title"><span class="tile-icon">${iconFor(view)}</span><h2>${c}</h2></div><span class="status">Bountiful</span></div><div class="big">${fmt(v.length)} <span class="muted">service visits</span></div><p>${['Pantry-based household grocery service.','Scheduled bus stops bringing food closer to home.','Food distribution at community partner sites.','Smaller neighborhood service events.'][i]}</p>${table(['Households','Person-visits','Pounds'],[[new Set(v.map(x=>x.household)).size,fmt(v.reduce((n,x)=>n+x.size,0)),fmt(v.reduce((n,x)=>n+x.pounds,0))]])}<button style="margin-top:18px" data-record="${c}">Record ${c} service</button></section>`}).join('')}</div>`}
if(view==='market'){html+=marketReporting(s.v.filter(x=>x.program==='Market'));}if(view==='imports'){html=importCenter();}
if(view==='mobile'){html+=offsiteLocations(s.v.filter(x=>['Mobile Bus','Mobile Truck'].includes(x.program)));html+=truckPanel();}if(view==='mini'){html+=offsiteLocations(s.v.filter(x=>x.program==='Mini Market'));}
if(view==='food'){let stock=['Produce','Dry goods','Dairy','Protein'].map(c=>[c,1800+s.f.filter(x=>x.category===c).reduce((n,x)=>n+x.pounds,0)-s.v.filter((x,i)=>i%4===['Produce','Dry goods','Dairy','Protein'].indexOf(c)).reduce((n,x)=>n+x.pounds,0)]);html=`<div class="metrics">${metric('Food received',s.incoming,'Pounds in selected period')}${metric('Grocery Rescue',s.rescue,'Included in food received')}${metric('Direct to clients',s.out,'From completed service records')}${metric('Partner transfers',data.outgoing.filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value).reduce((n,x)=>n+Number(x.pounds||0),0),'Recorded outgoing food (lb)')}</div><div class="grid equal"><section class="card"><h2>Receipt mix</h2>${bars(['Grocery Rescue','Community donation'].map(c=>[c,s.f.filter(x=>x.source===c).reduce((n,x)=>n+x.pounds,0)]),s.incoming)}</section><section class="card"><h2>Inventory reconciliation</h2><p class="muted">Inventory is managed in its separate monthly workspace. Opening balance, physical count and adjustments are not yet reconciled; no stock figure is inferred from service visits.</p><div class="notice"><strong>Periodic count supported in design</strong>Production inventory will reconcile physical counts with recorded movements.</div></section></div><section class="card" style="margin-top:22px"><div class="section-head"><h2>Food receipts</h2><div><button data-add="outgoing">Record partner transfer</button> <button id="exportFood">Export CSV</button></div></div>${table(['Date','Source','Partner','Category','Net lb'],s.f.slice().reverse().map(x=>[x.date,esc(x.source),esc(x.partner),esc(x.category),fmt(x.pounds)]))}</section><section class="card" style="margin-top:22px"><h2>Outgoing partner transfers</h2>${table(['Date','Destination','Category','Net lb'],data.outgoing.filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value).map(x=>[esc(x.date),esc(x.partner),esc(x.category),fmt(x.pounds)]))}</section><section class="card" style="margin-top:22px"><div class="section-head"><div><h2>Food donor history</h2><p class="muted">Donation frequency and weight by donor. Door donations remain anonymous and are excluded from letters.</p></div><button id="printDonorLetters">Print monthly thank-you letters</button></div>${donorHistory(s.f)}</section>`}
if(view==='packs'){html=`<div class="grid equal"><section class="card hero-card"><span class="eyebrow" style="color:#bdd7c5">PANTRY PACKS</span><h2>${fmt(s.packs)} packs completed</h2><p>Completed packs feed program reporting automatically.</p><button data-add="packs">Record completed packs</button></section><section class="card"><h2>Distribution planning</h2><p class="muted">Demo planning target · 2,400 packs this month</p><div class="progress"><i style="width:${Math.min(100,s.packs/2400*100)}%"></i></div><strong>${Math.round(s.packs/2400*100)}% of demo target</strong><p class="muted">Packing completion and school delivery will be separate records in production.</p></section></div><section class="card" style="margin-top:22px"><h2>Completion history</h2>${table(['Date','Location','Packs completed'],s.p.map(x=>[x.date,'Bountiful',fmt(x.count)]))}</section>`}
if(view==='geography'){html=`<div class="grid equal"><section class="card"><h2>Households by community</h2><p class="muted">Unique households within each city · not service locations</p>${bars(cities.map(c=>[c,new Set(s.v.filter(x=>x.city===c).map(x=>x.household)).size]),s.households)}</section><section class="card"><h2>Service reach</h2>${table(['Community','Unique households','Visits','Person-visits'],cities.map(c=>{let v=s.v.filter(x=>x.city===c);return[c,new Set(v.map(x=>x.household)).size,v.length,v.reduce((n,x)=>n+x.size,0)]}))}<p class="muted">Synthetic geography only. In production, residential geography stays separate from the pantry location that provided service.</p></section></div>`}
if(view==='reports'){html=`<section class="card"><div class="section-head"><div><h2>Operational summary</h2><p class="muted">All totals use the same date and location filters as the dashboard.</p></div><button id="exportSummary">Export CSV</button></div>${summary(s)}<div class="notice"><strong>Understand the measures</strong>Households are unique within the period. Individuals served counts person-visits. Food receipts and service distributions are separate movements. Prior-period comparison and partner distributions await a confirmed production reporting definition.</div></section>`}
if(view==='board'){html=preview?`<div class="toolbar no-print"><button id="editNotes">Edit narrative</button><button class="primary" id="print">Generate report / Save PDF</button><span class="muted">Use your browser’s “Save as PDF” destination.</span></div>${board(s)}`:`<div class="grid"><section class="card"><div class="section-head"><div><h2>1. Review the narrative</h2><span class="muted">Dates and location above apply to the entire report.</span></div><span class="status">Draft</span></div>${[['director',"Director’s notes"],['client','Client services notes'],['operations','Operations notes'],['capital','Capital campaign update']].map(([key,label])=>`<div class="note-field"><label for="note-${key}">${label}</label><textarea id="note-${key}" data-note="${key}">${esc(data.notes[key])}</textarea></div>`).join('')}<button class="primary" id="preview">Preview board report</button></section><section class="card"><h2>2. Confirm report inputs</h2><p class="muted">Operational figures are assembled automatically.</p>${summary(s)}<div class="note-field"><label for="volunteer">Volunteer hours · external summary</label><input id="volunteer" type="number" min="0" value="${data.volunteer}"><p class="muted">Demo monthly summary, maintained separately from service records. Excluded from date-filtered operational totals until dated imports are available.</p></div><div class="notice"><strong>Financials need an approved source</strong>Financial and development integrations are not connected. No financial figures are implied or generated.</div></section></div>`}
if(view==='board')html+=boardAggregateAppendix();$('#content').innerHTML=html;$('#content').setAttribute('data-view',view);if(view==='clients'){clientRows();$('#search').oninput=clientRows;$('#channel').onchange=clientRows}document.querySelectorAll('[data-note]').forEach(e=>e.oninput=()=>{data.notes[e.dataset.note]=e.value;save()});if($('#volunteer'))$('#volunteer').onchange=e=>{data.volunteer=Math.max(0,Number(e.target.value)||0);save()};}
function boardAggregateAppendix(){const from=$('#from').value,to=$('#to').value,months=marketAggregates().filter(x=>x.location==='bountiful'&&x.month+'-01'>=from.slice(0,7)+'-01'&&x.month+'-01'<=to.slice(0,7)+'-01').sort((a,b)=>a.month.localeCompare(b.month));if(!months.length)return '<section class="card"><h2>Imported Market aggregates</h2><p class="muted">No synthetic monthly aggregate imports for this period. The main board report continues to show demo service-activity figures.</p><button data-view="imports">Open Data Import Center</button></section>';const full=from.endsWith('-01')&&to===new Date(Number(to.slice(0,4)),Number(to.slice(5,7)),0).toLocaleDateString('en-CA').replace(/\//g,'-');return '<section class="card"><h2>Imported Market aggregates — separate reporting source</h2><p class="muted">Synthetic monthly source totals only. These are not added to or substituted for the board report’s daily service figures. '+(full?'Check month coverage before using any combined totals.':'The selected date range may include partial months; these imported figures represent entire months and must not be treated as date-exact.')+'</p>'+table(['Month','Duplicated HH','Unique HH','Duplicated people','Unique people','New clients','Outside Davis %','Shifts'],months.map(x=>[esc(x.month),fmt(x.duplicated_households),fmt(x.unduplicated_households),fmt(x.duplicated_individuals),fmt(x.unduplicated_individuals),fmt(x.new_clients),fmt(x.outside_davis_percent)+'%',fmt(x.market_shifts)]))+'<p class="muted">Monthly unique households and individuals cannot be summed into period-unique counts. County percentages cannot be averaged without denominators.</p></section>'}
function summary(s){return table(['Measure','Selected period'],[['Unique households',fmt(s.households)],['Service visits',fmt(s.visits)],['Individuals served (person-visits)',fmt(s.people)],['Food directly to clients (lb)',fmt(s.out)],['Food received (lb)',fmt(s.incoming)],['Grocery Rescue (lb)',fmt(s.rescue)],['Pantry Packs completed',fmt(s.packs)]])}
function board(s){
const period=new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric'}),pretty=date=>date?period.format(new Date(date+'T12:00:00')):'Date not selected';
const range=pretty($('#from').value)+' – '+pretty($('#to').value),location=$('#location').value==='all'?'Organization-wide · Bountiful active':'Bountiful';
const pct=n=>s.visits?Math.round(n/s.visits*100):0,colors=['#2a8a42','#1f63b2','#498ab5','#bf643e'];
const mark=(page,title)=>`<div class="report-masthead"><div class="report-brand"><img src="logo.png" alt="Bountiful Food Pantry"><div><strong>BOUNTIFUL FOOD PANTRY</strong><span>Board briefing · ${esc(title)}</span></div></div><span class="report-demo">SYNTHETIC DEMO</span></div>`;
const bottom=(n)=>`<div class="report-footer"><span>${esc(location)} · ${esc(range)}</span><strong>BOUNTIFUL / ${String(n).padStart(2,'0')}</strong></div>`;
const note=(key,label,number)=>`<section class="report-note"><div class="report-note-label"><span>${number}</span><h3>${label}</h3></div><p>${esc(data.notes[key])}</p></section>`;
return `<article class="paper board-brief"><section class="report-page report-impact">${mark(1,'Community impact')}<div class="report-cover"><div><span class="report-kicker">COMMUNITY IMPACT</span><h1>Good food.<br>Greater reach.</h1><p class="report-period">${esc(range)}</p><p class="report-scope">${esc(location)}</p></div><div class="report-cover-number"><strong>${fmt(s.households)}</strong><span>unique households<br>reached this period</span><div class="report-cover-rule"></div><small>Built from recorded service activity</small></div></div><div class="report-highlights"><div><span class="report-stat-icon">${iconFor('clients')}</span><strong>${fmt(s.visits)}</strong><span>service visits</span></div><div><span class="report-stat-icon">${iconFor('food')}</span><strong>${fmt(s.out)}</strong><span>pounds directly to households</span></div><div><span class="report-stat-icon">${iconFor('packs')}</span><strong>${fmt(s.packs)}</strong><span>Pantry Packs completed</span></div></div><div class="report-section-heading"><span>01 / SERVICE</span><h2>Every program. A shared purpose.</h2><p>Service visits by program in the selected period.</p></div><div class="report-service-mix">${channels.map((c,i)=>{const n=s.v.filter(x=>x.program===c).length;return `<div class="report-channel"><div class="report-channel-label"><strong>${c}</strong><span>${fmt(n)} visits <b>${pct(n)}%</b></span></div><div class="report-track"><i style="width:${s.visits?n/s.visits*100:0}%;background:${colors[i]}"></i></div></div>`}).join('')}</div><p class="report-caption">${fmt(s.people)} person-visits recorded. A household can receive service more than once; visits and unique households are different measures. Percentages are rounded.</p><section class="report-director"><span class="report-kicker">FROM THE DIRECTOR</span><h2>Perspective behind the numbers</h2><p>${esc(data.notes.director)}</p></section>${bottom(1)}</section><section class="report-page">${mark(2,'Operations & reach')}<div class="report-page-title"><span class="report-kicker">02 / OPERATIONS & REACH</span><h2>Food moving.<br>Communities connected.</h2><p>Recorded food movement and household geography.</p></div><div class="report-food-flow"><div><span>FOOD RECEIVED</span><strong>${fmt(s.incoming)}<small> lb</small></strong><p>Total incoming food</p></div><div><span>GROCERY RESCUE</span><strong>${fmt(s.rescue)}<small> lb</small></strong><p>Included in food received</p></div><div><span>DIRECT TO HOUSEHOLDS</span><strong>${fmt(s.out)}<small> lb</small></strong><p>Recorded with service visits</p></div></div><div class="report-section-heading"><h2>Service by program</h2></div>${table(['Program','Visits','Person-visits','Food (lb)'],channels.map(c=>{let v=s.v.filter(x=>x.program===c);return[c,fmt(v.length),fmt(v.reduce((n,x)=>n+x.size,0)),fmt(v.reduce((n,x)=>n+x.pounds,0))]}))}<div class="report-section-heading"><h2>Where households call home</h2><p>Residential geography, across all service channels.</p></div>${table(['Community','Unique households','Service visits'],cities.map(c=>{let v=s.v.filter(x=>x.city===c);return[c,fmt(new Set(v.map(x=>x.household)).size),fmt(v.length)]}))}<div class="report-program-strip"><span class="report-stat-icon">${iconFor('packs')}</span><div><h3>Pantry Packs</h3><p>Completed packs in this period</p></div><strong>${fmt(s.packs)}</strong></div><p class="report-caption">Food received and distributed are separate movements. These figures do not represent a physical inventory count. Northern Davis is planned and has no activity in this report.</p>${bottom(2)}</section><section class="report-page report-outlook">${mark(3,'Leadership outlook')}<div class="report-page-title"><span class="report-kicker">03 / LEADERSHIP OUTLOOK</span><h2>The work ahead.</h2><p>Leadership commentary, context, and reporting inputs.</p></div>${note('client','Client services','01')}${note('operations','Operations','02')}${note('capital','Capital campaign update','03')}<section class="report-external"><div class="report-external-heading"><span class="report-stat-icon">${iconFor('clients')}</span><div><h3>Volunteer contribution</h3><span>${s.volunteerData?'Connected demo · approved service':'External summary · synthetic demonstration'}</span></div><strong>${fmt(s.volunteerData?s.volunteerData.hours:data.volunteer)}<small> hours</small></strong></div><p>${s.volunteerData?`${fmt(s.volunteerData.people)} volunteers contributed approved time in the selected dates and location. Calculated from the volunteer prototype in this browser; pending time and planned bookings are excluded.`:'This is a separate, undated monthly summary. It is not filtered by this report’s dates. The existing volunteer system remains the source of truth.'}</p></section><section class="report-basis"><h3>About this report</h3><p>All figures and narratives are synthetic demonstration content. Operational measures are calculated from records within the selected dates and location. “Individuals served” means person-visits, including repeat service. Financial and development figures are not included because an approved source has not been connected.</p></section>${bottom(3)}</section></article>`;
}


const inventoryKey='bfp-demo-inventory-v1';
function inventoryRecords(){try{return JSON.parse(localStorage.getItem(inventoryKey))||[]}catch{return []}}
function inventoryPanel(s){const rows=inventoryRecords().filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value),incoming=s.incoming,partner=data.outgoing.filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value).reduce((n,x)=>n+Number(x.pounds||0),0),returns=rows.filter(x=>x.type==='return').reduce((n,x)=>n+x.pounds,0),disposed=rows.filter(x=>x.type==='disposal').reduce((n,x)=>n+x.pounds,0);return '<div class="metrics">'+metric('Received (lb)',incoming,'Recorded receipts')+metric('Partner transfers (lb)',partner,'Recorded outgoing')+metric('Returned (lb)',returns,'Separate adjustments')+metric('Disposed (lb)',disposed,'Separate adjustments')+'</div><section class="card"><h2>Monthly inventory movements</h2><p>Use this workspace to record truck returns and disposal separately. These are <strong>not</strong> a verified physical inventory or month-end balance; opening counts and Rachelle’s reconciliation rules are still required.</p><form id="inventoryEntry" class="planning-form"><label>Date<input name="date" type="date" required value="'+esc($('#to').value)+'"></label><label>Movement<select name="type"><option value="return">Returned from distribution</option><option value="disposal">Disposed / spoiled</option><option value="adjustment">Count adjustment (review required)</option></select></label><label>Weight (lb)<input name="pounds" type="number" min="0.01" step="0.01" required></label><label>Notes<input name="notes" type="text" required placeholder="Truck, location, reason"></label><button class="primary" type="submit">Save demo movement</button></form></section><section class="card"><div class="section-head"><h2>Recorded movements</h2><button id="exportInventory">Export movements CSV</button></div>'+table(['Date','Type','Pounds','Notes'],rows.map(x=>[esc(x.date),esc(x.type),fmt(x.pounds),esc(x.notes)]))+'</section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='inventoryEntry')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));x.pounds=Number(x.pounds);if(!Number.isFinite(x.pounds)||x.pounds<=0)return;const all=inventoryRecords();all.push(x);localStorage.setItem(inventoryKey,JSON.stringify(all));render();toast('Demo inventory movement saved.');});
const aggregateKey='bfp-demo-market-aggregates-v1';
function marketAggregates(){try{return JSON.parse(localStorage.getItem(aggregateKey))||[]}catch{return []}}
function aggregatePanel(){const rows=marketAggregates().filter(x=>x.month+'-01'>=$('#from').value.slice(0,7)+'-01'&&x.month+'-01'<=$('#to').value.slice(0,7)+'-01');return '<section class="card" style="margin-top:22px"><h2>Monthly aggregate reporting import</h2><p class="muted">For synthetic demonstration totals only. Do not import real PantrySoft exports, names, dates of birth, addresses, or any individual client records into this public browser demo.</p><p>Required CSV columns: <code>month,location,duplicated_households,unduplicated_households,duplicated_individuals,unduplicated_individuals,new_clients,outside_davis_percent,market_shifts</code>. Month format: YYYY-MM; location: bountiful. Reimporting a month replaces its earlier aggregate row.</p><button data-view="imports">Go to Data Import Center</button><p class="muted">Imported totals are shown separately from simulated visit calculations; they do not silently overwrite the board report.</p>'+table(['Month','Location','Duplicated households','Unduplicated households','Duplicated individuals','Unduplicated individuals','New clients','Outside Davis %','Shifts'],rows.map(x=>[esc(x.month),esc(x.location),fmt(x.duplicated_households),fmt(x.unduplicated_households),fmt(x.duplicated_individuals),fmt(x.unduplicated_individuals),fmt(x.new_clients),fmt(x.outside_davis_percent)+'%',fmt(x.market_shifts)]))+'</section>'}
function parseAggregateCsv(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const columns=['month','location','duplicated_households','unduplicated_households','duplicated_individuals','unduplicated_individuals','new_clients','outside_davis_percent','market_shifts'];if(lines.length<2||lines.length>121)throw Error('CSV must have a header and 1–120 aggregate rows.');const header=lines.shift().split(',').map(x=>x.trim());if(header.length!==columns.length||columns.some((x,i)=>header[i]!==x))throw Error('CSV columns do not match the aggregate template.');const results=[];for(const line of lines){if(!line.trim())continue;const cells=line.split(',').map(x=>x.trim());if(cells.length!==columns.length)throw Error('Invalid CSV row; use numeric aggregates without embedded commas.');const x=Object.fromEntries(columns.map((k,i)=>[k,cells[i]]));if(!/^20\d\d-(0[1-9]|1[0-2])$/.test(x.month)||x.location!=='bountiful')throw Error('Use YYYY-MM and location bountiful.');for(const k of columns.slice(2)){if(!/^\d+(\.\d+)?$/.test(x[k]))throw Error('Only nonnegative numeric totals are allowed.');x[k]=Number(x[k]);if(!Number.isFinite(x[k]))throw Error('Invalid number.')}for(const k of columns.slice(2).filter(k=>k!=='outside_davis_percent'))if(!Number.isInteger(x[k]))throw Error('Counts and shifts must be whole numbers.');if(x.outside_davis_percent>100||x.unduplicated_households>x.duplicated_households||x.unduplicated_individuals>x.duplicated_individuals)throw Error('Aggregate totals are inconsistent.');results.push(x)}if(!results.length)throw Error('No rows found.');return results}
document.addEventListener('change',e=>{if(e.target.id==='aggregateCsv')stageAggregate(e.target.files?.[0])})
const importTypes=[{id:'market',name:'Client Services / PantrySoft',desc:'Monthly aggregate household and individual totals',ready:true},{id:'offsite',name:'Off-site Services',desc:'Truck, bus and Mini Market tracking sheets'},{id:'food',name:'Food & Inventory',desc:'Receipts, rescue and warehouse reconciliations'},{id:'volunteers',name:'Volunteer Hours',desc:'Approved volunteer activity summaries'},{id:'engagement',name:'Community Engagement',desc:'Website, social media and newsletters'},{id:'financial',name:'Financial Reports',desc:'Monthly financial summary exports'}];
let selectedImport='market',stagedImport=null;
function importCenter(){const active=importTypes.find(x=>x.id===selectedImport)||importTypes[0];const history=importHistory();return '<p class="muted">Select a source, drop a file, review the results, and confirm. This public demo accepts <strong>synthetic aggregate data only</strong> — never actual client, donor or volunteer records.</p><div class="grid equal">'+importTypes.map(x=>'<section class="card"><h2>'+esc(x.name)+'</h2><p>'+esc(x.desc)+'</p><p class="muted">'+(x.ready?'Demo CSV importer ready':'Awaiting source CSV sample and field mapping')+'</p><button data-import="'+x.id+'">'+(x.ready?'Open importer':'View requirements')+'</button></section>').join('')+'</div><section class="card" style="margin-top:22px"><h2>'+esc(active.name)+'</h2>'+(active.ready?'<p>Use the blank template to prepare <strong>fictional monthly aggregate totals</strong>. Actual PantrySoft CSV formats will need approved mapping before production.</p><button id="aggregateTemplate">Download CSV template</button><div id="importDrop" role="button" tabindex="0" style="border:2px dashed currentColor;border-radius:12px;padding:30px;text-align:center;margin:18px 0;cursor:pointer"><strong>Drop a synthetic CSV here</strong><p>or click to choose a file (maximum 50 KB)</p><input id="aggregateCsv" type="file" accept=".csv,text/csv" style="max-width:100%"></div><div id="importReview">'+(stagedImport?'<h3>Review before importing</h3><p>'+stagedImport.length+' monthly aggregate row(s) ready. Existing months will be replaced only after confirmation.</p>'+table(['Month','Location','Duplicated households','Unduplicated households','New clients'],stagedImport.map(x=>[esc(x.month),esc(x.location),fmt(x.duplicated_households),fmt(x.unduplicated_households),fmt(x.new_clients)]))+'<button class="primary" id="confirmAggregate">Confirm synthetic import</button> <button id="cancelAggregate">Cancel</button>':'<p class="muted">No file staged. Your data will not change until you confirm.</p>')+'</div>':'<p class="muted">This importer is not active yet. We need a sample export and approved field mapping before files can be routed safely. No data will be imported here.</p>')+'</section><section class="card" style="margin-top:22px"><h2>Recent demo imports</h2>'+table(['Imported at','Source','Reporting months','Rows'],history.slice(-12).reverse().map(x=>[esc(x.at),esc(x.source),esc(x.months),fmt(x.count)]))+'<p class="muted">This history is stored only in this browser. Production will require staff identity, audit history and permission controls.</p></section>'}
const importHistoryKey='bfp-demo-import-history-v1';
function importHistory(){try{return JSON.parse(localStorage.getItem(importHistoryKey))||[]}catch{return []}}
function stageAggregate(file){if(!file)return;if(file.size>50000){toast('CSV too large for aggregate demo.');return}file.text().then(t=>{stagedImport=parseAggregateCsv(t);render();toast('CSV validated. Review and confirm import.');}).catch(err=>{stagedImport=null;toast(err.message)})}
document.addEventListener('dragover',e=>{if(e.target.closest('#importDrop'))e.preventDefault()});
document.addEventListener('drop',e=>{if(!e.target.closest('#importDrop'))return;e.preventDefault();stageAggregate(e.dataTransfer.files[0])});
function marketReporting(visits){const households=new Map();for(const x of visits){const id=x.household;const row=households.get(id)||{size:0};row.size=Math.max(row.size,Number(x.size)||0);households.set(id,row)}const dupHouseholds=visits.length,dupIndividuals=visits.reduce((n,x)=>n+(Number(x.size)||0),0),undupHouseholds=households.size,householdMemberEstimate=[...households.values()].reduce((n,x)=>n+x.size,0),pounds=visits.reduce((n,x)=>n+(Number(x.pounds)||0),0);const shifts=new Set(visits.map(x=>x.date)).size;const fmtRatio=(a,b)=>b?(Math.round(a/b*100)/100).toLocaleString('en-US'):'—';return '<section class="card" style="margin-top:22px"><div class="section-head"><div><h2>Market reporting calculations</h2><p class="muted">Calculated from fictional Market visits for the selected dates. These are not PantrySoft figures.</p></div><button id="exportMarket">Export Market summary</button></div><div class="metrics">'+metric('Duplicated households',dupHouseholds,'One per recorded Market visit')+metric('Unduplicated households',undupHouseholds,'Distinct household identifiers')+metric('Duplicated individuals',dupIndividuals,'Sum of members across visits')+metric('Estimated unique members',householdMemberEstimate,'Not verified individual identities')+'</div>'+table(['Measure','Calculated value','Basis'],[['Average pounds per household visit',fmtRatio(pounds,dupHouseholds)+' lb','Market pounds ÷ duplicated households'],['Average pounds per person-visit',fmtRatio(pounds,dupIndividuals)+' lb','Market pounds ÷ duplicated individuals'],['Average households per active date',fmtRatio(dupHouseholds,shifts),'Visits ÷ dates with recorded visits; not actual staffed shifts'],['New clients','Awaiting aggregate import','First-ever client status cannot be confirmed from this demo'],['Outside Davis County (%)','Awaiting aggregate import','City Other is not evidence of county of residence']])+'<p class="muted">For actual Market shifts, verified unduplicated individuals, new clients, and county-of-residence percentages, import approved aggregate PantrySoft figures. No individual client records should be uploaded to this public demo.</p></section>'}
function offsiteLocations(visits){const groups=new Map();for(const x of visits){const stop=(x.stop||'Unassigned / historical demo').trim();const key=x.program+'|'+stop;const row=groups.get(key)||{program:x.program,stop,visits:0,people:0,households:new Set()};row.visits++;row.people+=Number(x.size)||0;row.households.add(x.household);groups.set(key,row)}return '<section class="card" style="margin-top:22px"><h2>Service by off-site location</h2><p class="muted">Location is the service stop, not the household’s residential city. Historical demo visits without a stop remain unassigned rather than being attributed to a guessed location.</p>'+table(['Program','Service stop','Visits','Person-visits','Unique households'],[...groups.values()].sort((a,b)=>b.visits-a.visits).map(x=>[esc(x.program),esc(x.stop),fmt(x.visits),fmt(x.people),fmt(x.households.size)]))+'</section>'}
const truckKey='bfp-demo-truck-runs-v1';
function truckRuns(){try{return JSON.parse(localStorage.getItem(truckKey))||[]}catch{return []}}
function truckPanel(){const rows=truckRuns().filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value),sum=k=>rows.reduce((n,x)=>n+Number(x[k]||0),0);return '<section class="card" style="margin-top:22px"><div class="section-head"><div><h2>Mobile Truck load reconciliation</h2><p class="muted">Track food leaving the warehouse and food returning. Truck load totals are separate from household service visits, so they are not added to client counts.</p></div><button id="exportTruck">Export runs CSV</button></div><div class="metrics">'+metric('Loaded (lb)',sum('loaded'),'Outbound weight')+metric('Returned (lb)',sum('returned'),'Unused food returned')+metric('Transferred (lb)',sum('transferred'),'To other organizations')+metric('Reconciled distribution (lb)',sum('distributed'),'Loaded − returned − transfers − disposal')+'<div class="notice"><strong>Average distributed pounds per truck run:</strong> '+(rows.length?fmt(Math.round(sum('distributed')/rows.length*100)/100):'—')+' lb across '+fmt(rows.length)+' recorded run(s). This is not pounds per household or pounds per bus service.</div></div><form id="truckEntry" class="planning-form"><label>Run date<input name="date" type="date" required value="'+esc($('#to').value)+'"></label><label>Service location / stop<input name="stop" type="text" required placeholder="Demo community partner"></label><label>Loaded (lb)<input name="loaded" type="number" min="0" step="0.01" required></label><label>Returned (lb)<input name="returned" type="number" min="0" step="0.01" value="0" required></label><label>Transferred to partners (lb)<input name="transferred" type="number" min="0" step="0.01" value="0" required></label><label>Disposed (lb)<input name="disposed" type="number" min="0" step="0.01" value="0" required></label><button class="primary" type="submit">Reconcile demo run</button></form><p class="muted">These weights are demonstration-only. Confirm Tryn’s exact reconciliation rules before using production reports. Do not record the same return a second time as an inventory adjustment.</p>'+table(['Date','Stop','Loaded','Returned','Transfers','Disposal','Distributed'],rows.map(x=>[esc(x.date),esc(x.stop),fmt(x.loaded),fmt(x.returned),fmt(x.transferred),fmt(x.disposed),fmt(x.distributed)]))+'</section>'}
document.addEventListener('submit',e=>{if(e.target.id!=='truckEntry')return;e.preventDefault();const x=Object.fromEntries(new FormData(e.target));for(const k of ['loaded','returned','transferred','disposed'])x[k]=Number(x[k]);if(['loaded','returned','transferred','disposed'].some(k=>!Number.isFinite(x[k])||x[k]<0)||x.returned+x.transferred+x.disposed>x.loaded){toast('Check weights: returned, transferred and disposed cannot exceed loaded.');return}x.distributed=Math.round((x.loaded-x.returned-x.transferred-x.disposed)*100)/100;const all=truckRuns();all.push(x);localStorage.setItem(truckKey,JSON.stringify(all));render();toast('Demo truck run reconciled.');});
function donorHistory(food){const groups=new Map();for(const x of food){const name=(x.partner||'Door').trim();const key=name.toLowerCase();const current=groups.get(key)||{name,count:0,pounds:0};current.count++;current.pounds+=Number(x.pounds)||0;groups.set(key,current)}return table(['Donor','Receipts','Pounds received'],[...groups.values()].sort((a,b)=>b.pounds-a.pounds).map(x=>[esc(x.name),fmt(x.count),fmt(x.pounds)]))}
function printDonorLetters(){const from=$('#from').value,to=$('#to').value;const rows=stats().f.filter(x=>x.source!=='Grocery Rescue'&&(x.partner||'').trim().toLowerCase()!=='door');const groups=new Map();for(const x of rows){const name=(x.partner||'').trim();if(!name)continue;const key=name.toLowerCase();const current=groups.get(key)||{name,count:0,pounds:0};current.count++;current.pounds+=Number(x.pounds)||0;groups.set(key,current)}if(!groups.size){toast('No named community donors in the selected dates.');return}const pages=[...groups.values()].map(x=>'<article style="break-after:page;padding:45px;font-family:Georgia,serif"><h2>Bountiful Food Pantry</h2><p>DEMONSTRATION LETTER — NOT FOR MAILING</p><p>'+esc(to)+'</p><p>Dear '+esc(x.name)+',</p><p>Thank you for supporting Bountiful Food Pantry. During '+esc(from)+' through '+esc(to)+', our records show '+fmt(x.count)+' food donation(s), totaling '+fmt(x.pounds)+' pounds.</p><p>Your generosity helps us serve our neighbors.</p><p>With gratitude,<br>Bountiful Food Pantry</p><small>Fictional demonstration data. Verify donor identity, address and totals before production mailing.</small></article>').join('');const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print donor letters.');return}w.document.write('<!doctype html><html><head><title>Demo donor letters</title></head><body>'+pages+'</body></html>');w.document.close();w.focus();w.print()}
function clientRows(){let q=$('#search').value.toLowerCase(),c=$('#channel').value,v=stats().v.filter(x=>(!c||x.program===c)&&[x.household,x.city,x.id].join(' ').toLowerCase().includes(q));$('#clientRows').innerHTML=table(['Household','City','Members','Channel','Date','Action'],v.slice().reverse().slice(0,50).map(x=>[`<strong>${esc(x.household)}</strong><div class="muted">${x.id}</div>`,esc(x.city),x.size,esc(x.program),x.date,`<button data-repeat="${x.id}">Record visit</button>`]))}
let entryType='service';function weightFields(kind){return '<fieldset style="border:1px solid #ccd8cd;border-radius:12px;padding:12px"><legend>Scale entry (pounds)</legend><label>Gross scale weight (lb)<input required name="gross" type="number" min="0" step="0.01" value="'+(kind==='food'?'220':'120')+'"></label><label>Container / tare type<select name="tareType"><option value="none">No container</option><option value="small">Small Gaylord — example 20 lb</option><option value="large">Large Gaylord — example 35 lb</option><option value="pallet">Pallet — example 45 lb</option><option value="custom">Custom tare</option></select></label><label>Custom tare (lb, only when custom selected)<input name="customTare" type="number" min="0" step="0.01" value="0"></label><p class="muted">Net weight = gross − tare. Container weights are illustrative placeholders until Rachelle confirms the real tare schedule. The saved entry stores all weights.</p></fieldset>'}
function openEntry(type='service',program='Market',repeat){entryType=type;$('#modalTitle').textContent=type==='food'?'Receive food':type==='outgoing'?'Record outgoing food':type==='packs'?'Record completed packs':'Record a service visit';let field=(label,name,kind='text',val='',min='')=>`<label>${label}<input required name="${name}" type="${kind}" value="${esc(val)}" ${min?'min="'+min+'"':''}></label>`,select=(label,name,options,val)=>`<label>${label}<select name="${name}">${options.map(c=>`<option ${val===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;$('#fields').innerHTML=field('Activity date','date','date',$('#to').value)+(type==='service'?field('Demo household name','household','text',repeat?.household||'')+field('Household members','size','number',repeat?.size||3,'1')+select('Home community','city',cities,repeat?.city)+select('Service channel','program',channels,program)+field('Food distributed (lb)','pounds','number',30,'1')+(program==='Mobile Truck'||program==='Mobile Bus'||program==='Mini Market'?'<label>Off-site stop / location<input name="stop" type="text" required placeholder="Demo location name"></label>':''):type==='outgoing'?field('Destination pantry / partner','partner')+select('Food category','category',['Produce','Dry goods','Dairy','Protein','Bakery','Frozen','Other'])+weightFields('outgoing'):type==='food'?select('Source','source',['Grocery Rescue','Community donation'])+field('Donor name (or Door for anonymous)','partner')+select('Food category','category',['Produce','Dry goods','Dairy','Protein'])+weightFields('food'):field('Packs completed','count','number',100,'1'));$('#modal').showModal()}
$('#entry').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));for(let key of ['size','pounds','count'])if(x[key])x[key]=Number(x[key]);if(entryType==='food'||entryType==='outgoing'){const tare={none:0,small:20,large:35,pallet:45,custom:Number(x.customTare||0)}[x.tareType];x.gross=Number(x.gross);x.tare=Number(tare);x.pounds=Math.round((x.gross-x.tare)*100)/100;if(!Number.isFinite(x.pounds)||x.pounds<=0){toast('Net weight must be greater than zero. Check gross and tare weights.');return;}}x.location='bountiful';x.id='DEMO-'+Date.now();if(entryType==='service')data.visits.push(x);else if(entryType==='food')data.food.push(x);else if(entryType==='outgoing')data.outgoing.push(x);else data.packs.push(x);save();$('#modal').close();render();toast('Record saved. Dashboards and reports updated.');};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function csv(name,rows){let b=new Blob([rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;preview=false;render();window.scrollTo({top:0,behavior:'instant'})}if(b.dataset.record)openEntry('service',b.dataset.record);if(b.dataset.add)openEntry(b.dataset.add);if(b.dataset.repeat){let r=data.visits.find(x=>x.id===b.dataset.repeat);openEntry('service',r.program,r)}if(['preview','mainAction'].includes(b.id)){if(view==='board'){preview=true;render()}else openEntry(view==='food'?'food':view==='packs'?'packs':'service',view==='mobile'?'Mobile Bus':view==='mini'?'Mini Market':'Market')}if(b.id==='editNotes'){preview=false;render()}if(b.id==='print')window.print();if(b.dataset.import){selectedImport=b.dataset.import;stagedImport=null;render();}if(b.id==='cancelAggregate'){stagedImport=null;render();}if(b.id==='confirmAggregate'&&stagedImport){const merged=new Map(marketAggregates().map(x=>[x.month+'|'+x.location,x]));for(const x of stagedImport)merged.set(x.month+'|'+x.location,x);localStorage.setItem(aggregateKey,JSON.stringify([...merged.values()]));const history=importHistory();history.push({at:new Date().toLocaleString(),source:'Client Services / synthetic aggregate',months:stagedImport.map(x=>x.month).join(', '),count:stagedImport.length});localStorage.setItem(importHistoryKey,JSON.stringify(history));const count=stagedImport.length;stagedImport=null;render();toast(count+' synthetic monthly aggregate row(s) imported.');}if(b.id==='aggregateTemplate')csv('bfp-synthetic-monthly-aggregates-template.csv',[['month','location','duplicated_households','unduplicated_households','duplicated_individuals','unduplicated_individuals','new_clients','outside_davis_percent','market_shifts']]);if(b.id==='exportMarket'){const v=stats().v.filter(x=>x.program==='Market');const households=new Set(v.map(x=>x.household));const people=v.reduce((n,x)=>n+Number(x.size||0),0);const pounds=v.reduce((n,x)=>n+Number(x.pounds||0),0);csv('bfp-demo-market-summary.csv',[['From','To','Duplicated households','Unduplicated households','Duplicated individuals','Pounds','Avg pounds per household visit','Avg pounds per person-visit'],[$('#from').value,$('#to').value,v.length,households.size,people,pounds,v.length?pounds/v.length:0,people?pounds/people:0]])};if(b.id==='exportTruck')csv('bfp-demo-truck-runs.csv',[['Date','Stop','Loaded','Returned','Transferred','Disposed','Distributed'],...truckRuns().map(x=>[x.date,x.stop,x.loaded,x.returned,x.transferred,x.disposed,x.distributed])]);if(b.id==='exportInventory')csv('bfp-demo-inventory-movements.csv',[['Date','Type','Pounds','Notes'],...inventoryRecords().map(x=>[x.date,x.type,x.pounds,x.notes])]);if(b.id==='printDonorLetters')printDonorLetters();if(b.id==='exportFood')csv('bountiful-demo-food.csv',[['Date','Source','Partner','Category','Pounds'],...stats().f.map(x=>[x.date,x.source,x.partner,x.category,x.pounds])]);if(b.id==='exportSummary'){let s=stats();csv('bountiful-demo-summary.csv',[['From','To','Location','Households','Visits','Person-visits','Received lb','Distributed lb','Packs'],[$('#from').value,$('#to').value,$('#location').value,s.households,s.visits,s.people,s.incoming,s.out,s.packs]])}});
$('#close').onclick=()=>$('#modal').close();for(let id of ['from','to','location'])$('#'+id).onchange=render;$('#reset').onclick=()=>{if(confirm('Reset all synthetic records and edited notes?')){data=seed();save();render();toast('Demo reset.')}};render();


window.addEventListener('storage',e=>{if(e.key==='bfp-volunteers-v1')render()});
window.addEventListener('focus',()=>render());
